import * as React from "react"
import { graphql } from "gatsby"
import { GatsbyImage, getImage, IGatsbyImageData } from "gatsby-plugin-image"

import "../scss/main.scss"

import Header from "../components/Header"

interface PageProps {
  data: {
    file: {
      childImageSharp: {
        gatsbyImageData: IGatsbyImageData
      }
    }
  }
}

const About: React.FC<PageProps> = ({ data }) => {
  const profileImage = getImage(data.file.childImageSharp.gatsbyImageData)

  return (
    <div className="container">
      <Header />
      <div className="home-hero">
        <div className="home-content">
          <div className="profile-image-container">
            {profileImage && (
              <GatsbyImage
                image={profileImage}
                alt="Jayne Hepburn"
                className="profile-image"
              />
            )}
          </div>
          <div className="bio-container">
            <h1>Hi, I'm [Your Name]</h1>
            <p className="bio-text">
              [Your bio goes here. Share a bit about yourself, your work, your passions,
              and what drives you creatively. This is your space to introduce yourself
              to visitors and give them a sense of who you are.]
            </p>
            <p className="bio-text">
              [You can add more paragraphs here to tell your story, describe your
              background, or highlight your skills and interests.]
            </p>
          </div>
        </div>
      </div>
    </div>
  )
}

export const query = graphql`
  query AboutPageQuery {
    file(sourceInstanceName: { eq: "profile" }, relativePath: { eq: "me.png" }) {
      childImageSharp {
        gatsbyImageData(
          width: 800
          placeholder: BLURRED
          transformOptions: { fit: COVER, cropFocus: CENTER }
        )
      }
    }
  }
`

export default About
